    [Theory]
    [MemberData(nameof(WordDefinitions))]
    public void ConditionalMarkerCapsMatchVisibleWord(string name, string numberingXml,
        string documentXml, string stylesXml, string[] expected)
    {
        using var stream = new MemoryStream();
        using var doc = WordprocessingDocument.Create(stream, WordprocessingDocumentType.Document);
        var main = doc.AddMainDocumentPart();
        var numbering = new Numbering(numberingXml);
        main.AddNewPart<NumberingDefinitionsPart>().Numbering = numbering;
        main.Document = new Document(documentXml);
        main.AddNewPart<StyleDefinitionsPart>().Styles = new Styles(stylesXml);
        _ = numbering.Descendants().ToArray();
        _ = main.Document.Descendants().ToArray();
        _ = main.StyleDefinitionsPart!.Styles.Descendants().ToArray();
        var before = new[] { numbering.OuterXml, main.Document.OuterXml, main.StyleDefinitionsPart.Styles.OuterXml };
        DxpITextVisitor[] visitors = [new DxpMarkdownVisitor(DxpMarkdownVisitorConfig.CreatePlainConfig()),
            new DxpHtmlVisitor(DxpHtmlVisitorConfig.CreatePlainConfig()),
            new DxpHtmlVisitor(DxpHtmlVisitorConfig.CreateRichConfig()),
            new DxpMarkdownVisitor(DxpMarkdownVisitorConfig.CreateRichConfig()),
            new DxpPlainTextVisitor(DxpPlainTextVisitorConfig.CreateAcceptConfig())];
        foreach (var visitor in visitors)
        {
            var output = DxpExport.ExportToString(doc, visitor);
            if (visitor is DxpHtmlVisitor or DxpMarkdownVisitor)
                output = new HtmlParser().ParseDocument(output).Body!.TextContent;
            Assert.Equal(expected, Regex.Matches(output, @"BEGIN.*?END").Select(m => m.Value));
            Assert.Equal(Enumerable.Range(0, 6).Select(i => "Item" + i), Regex.Matches(output, @"Item[0-5]").Select(m => m.Value));
            Assert.Equal(before, new[] { numbering.OuterXml, main.Document.OuterXml, main.StyleDefinitionsPart.Styles.OuterXml });
        }
    }
